import { createHash, randomBytes } from 'node:crypto';

/**
 * Opaque bearer secrets: share-link tokens and refresh tokens.
 *
 * Both are treated like passwords that nobody has to remember:
 *   - generated by a cryptographically secure random source, never guessable;
 *   - stored only as a SHA-256 hash, so a database dump grants nobody access;
 *   - shown to their holder, never read back from the database.
 *
 * SHA-256 without a salt is deliberate here, unlike for passwords: the token
 * already has 256 bits of entropy, so there is nothing to brute force or to
 * look up in a rainbow table, and lookups have to stay a single indexed query.
 */

/** 32 random bytes as base64url - 43 URL- and cookie-safe characters. */
export function randomToken(): { token: string; tokenHash: string } {
  const token = randomBytes(32).toString('base64url');
  return { token, tokenHash: hashToken(token) };
}

export function hashToken(token: string): string {
  return createHash('sha256').update(token).digest('hex');
}
